#!/usr/bin/env node

// Test script for MCP Inspector
// This script helps you test the MCP server with proper environment setup

import { spawn } from 'child_process';
import { config } from '../src/config/index.js';
import { logger } from '../src/utils/logger.js';

console.log('🚀 MCP Inspector Test Script');
console.log('=====================================');

// Check environment variables
if (!config.auth.token) {
  console.error('❌ GET_NOTE_API_KEY is not set');
  console.log('Please set: export GET_NOTE_API_KEY="your-api-key-here"');
  process.exit(1);
}

console.log('✅ Environment variables configured:');
console.log(`   API Key: ${config.auth.token.substring(0, 8)}...`);
console.log(`   Topic ID: ${config.knowledgeBase.topicId || 'Not set (optional)'}`);

// Test commands for Inspector
const testCommands = [
  {
    name: 'List Tools',
    method: 'tools/list',
    params: {}
  },
  {
    name: 'Search Knowledge',
    method: 'tools/call',
    params: {
      name: 'search_knowledge',
      arguments: {
        question: "What are the key insights from New Year speeches?",
        topic_ids: [config.knowledgeBase.topicId || "test-topic"],
        deep_seek: true,
        refs: false
      }
    }
  },
  {
    name: 'Recall Knowledge',
    method: 'tools/call',
    params: {
      name: 'recall_knowledge',
      arguments: {
        question: "test query",
        topic_id: config.knowledgeBase.topicId || "test-topic",
        top_k: 3
      }
    }
  }
];

console.log('');
console.log('📋 Test Commands for MCP Inspector:');
console.log('=====================================');

testCommands.forEach((cmd, index) => {
  console.log(`\n${index + 1}. ${cmd.name}:`);
  console.log(`   Method: ${cmd.method}`);
  console.log(`   Params: ${JSON.stringify(cmd.params, null, 2)}`);
});

console.log('');
console.log('🎯 Inspector Setup Instructions:');
console.log('=====================================');
console.log('');
console.log('1. Start Inspector:');
console.log('   npx @modelcontextprotocol/inspector');
console.log('');
console.log('2. In the Inspector interface, configure:');
console.log('   Command: npx');
console.log('   Arguments: get-biji-mcp');
console.log('   Environment: ');
console.log(`     GET_NOTE_API_KEY=${config.auth.token}`);
console.log(`     GET_NOTE_TOPIC_ID=${config.knowledgeBase.topicId || 'your-topic-id'}`);
console.log('');
console.log('3. Choose transport mode:');
console.log('   - STDIO: Leave arguments as "get-biji-mcp"');
console.log('   - SSE: Add "--transport sse --port 3000"');
console.log('   - HTTP: Add "--transport http --port 8080"');
console.log('');
console.log('4. Click "Connect" and test the commands above');
console.log('');
console.log('🚀 Alternative: Direct MCP commands');
console.log('=====================================');
console.log('');
console.log('You can also test directly with these commands:');
console.log('');
testCommands.forEach((cmd, index) => {
  const jsonCmd = JSON.stringify({
    jsonrpc: "2.0",
    method: cmd.method,
    id: index + 1,
    params: cmd.params
  }, null, 2);
  
  console.log(`${index + 1}. ${cmd.name}:`);
  console.log(`   echo '${jsonCmd}' | npx get-biji-mcp`);
  console.log('');
});

console.log('✅ Test script ready!');
console.log('');
console.log('🎯 Next Steps:');
console.log('1. Start Inspector: npx @modelcontextprotocol/inspector');
console.log('2. Configure with your API key');
console.log('3. Test the commands above');
console.log('4. Verify all functionality works');
console.log('');
console.log('🎉 Happy testing!');